#include "status_view.h"
#include "display_logic.h"
#include <stdio.h>
#include <string.h>

/* -----------------------------------------------------------------------
 * put_left / put_centred
 * Write src into out as exactly width characters, padded with spaces
 * (cut at width), then the NUL; out holds width + 1 bytes. put_left can
 * upper-case on the way: size-1 text on the panel is upper case.
 * ----------------------------------------------------------------------- */
static void put_left(char *out, size_t width, const char *src, bool upper)
{
    size_t i = 0U;

    if (src != NULL) {
        for (; i < width && src[i] != '\0'; i++) {
            char c = src[i];
            if (upper && c >= 'a' && c <= 'z') {
                c = (char)(c - 'a' + 'A');
            }
            out[i] = c;
        }
    }
    for (; i < width; i++) {
        out[i] = ' ';
    }
    out[width] = '\0';
}

/* The spare columns go half before and half after, the odd one after
 * (the same rounding as the firmware's draw_centred). */
static void put_centred(char *out, size_t width, const char *src)
{
    size_t len = strlen(src);

    if (len > width) {
        len = width;
    }
    memset(out, ' ', width);
    memcpy(&out[(width - len) / 2U], src, len);
    out[width] = '\0';
}

/* Exact match without reading more of text than want needs (want's own
 * length + its NUL), so a text with no NUL cannot be overrun. */
static bool text_is(const char *text, const char *want)
{
    return (text != NULL) && (strncmp(text, want, strlen(want) + 1U) == 0);
}

/* -----------------------------------------------------------------------
 * Header
 * ----------------------------------------------------------------------- */

/* The tag: the one thing about the battery that matters most now. */
static const char *header_tag(const ui_state_t *s, sv_colour_t *colour)
{
    if (s->speaker_locked) {
        *colour = SV_RED;
        return "SPEAKER LOCKED";
    }
    if (s->battery_soc_override) {
        *colour = SV_MAGENTA;           /* the SoC shown is not measured */
        return "SOC OVERRIDE";
    }
    if (!s->battery_valid) {
        *colour = SV_DARKGREY;
        return "NO GAUGE";
    }
    if (s->battery_charger_fault) {
        *colour = SV_RED;
        return "CHARGER FAULT";
    }
    if (s->battery_charging) {
        *colour = SV_CYAN;
        return "CHARGING";
    }
    if (s->battery_critical) {
        *colour = SV_RED;
        return "CRITICAL";
    }
    if (s->battery_low) {
        *colour = SV_YELLOW;
        return "LOW BATTERY";
    }
    if (s->battery_ext_power) {
        *colour = SV_LIGHTGREY;         /* power good but not charging: full */
        return "ON USB POWER";
    }
    *colour = SV_LIGHTGREY;
    return "BATTERY";
}

/* The SoC / icon colour. Valid readings get the old status-bar rule;
 * without one there is no charge to colour, so grey. The lockout stays
 * red either way: it holds up to 32 %, after critical has released. */
static sv_colour_t level_colour(const ui_state_t *s)
{
    if (s->speaker_locked) {
        return SV_RED;
    }
    if (!s->battery_valid) {
        return SV_DARKGREY;
    }
    if (s->battery_critical) {
        return SV_RED;
    }
    if (s->battery_low) {
        return SV_YELLOW;
    }
    return SV_GREENYELLOW;
}

void sv_build_header(const ui_state_t *s, sv_header_t *out)
{
    if (s == NULL || out == NULL) {
        return;
    }
    memset(out, 0, sizeof(*out));

    put_left(out->tag, SV_TAG_W, header_tag(s, &out->tag_colour), false);

    out->level_colour = level_colour(s);
    out->nub_colour   = s->battery_charging ? SV_CYAN : out->level_colour;
    if (s->battery_valid) {
        uint32_t pct = (s->battery_pct > 100U) ? 100U : s->battery_pct;
        out->fill_px = (uint8_t)((pct * SV_FILL_MAX + 50U) / 100U);
        snprintf(out->soc, sizeof(out->soc), "%3u%%", (unsigned)s->battery_pct);
    } else {
        /* No made-up number: the old mV estimate is gone too. */
        out->fill_px = 0U;
        snprintf(out->soc, sizeof(out->soc), " --%%");
    }

    ui_format_hhmm(s->battery_tte_min, out->tte, sizeof(out->tte));
    out->tte_colour = (s->battery_tte_min == UI_TIME_UNKNOWN) ? SV_DARKGREY : SV_WHITE;
    ui_format_hhmm(s->battery_ttf_min, out->ttf, sizeof(out->ttf));
    out->ttf_colour = (s->battery_ttf_min == UI_TIME_UNKNOWN) ? SV_DARKGREY : SV_WHITE;
}

/* -----------------------------------------------------------------------
 * sv_sd_chip
 * ----------------------------------------------------------------------- */
void sv_sd_chip(const sv_sd_in_t *sd, sv_chip_t *out)
{
    const char *text;

    if (out == NULL) {
        return;
    }
    if (sd == NULL || !sd->have_status) {
        text = "SD ...";
        out->bg = SV_DARKGREY;
        out->fg = SV_WHITE;
    } else if (sd->msc_mode) {
        text = "SD USB";
        out->bg = SV_CYAN;
        out->fg = SV_BLACK;
    } else if (sd->recording || sd->playing != SV_PLAYING_IDLE || sd->fx_busy) {
        text = "SD BUSY";               /* a file is open or being written: do not pull */
        out->bg = SV_ORANGE;
        out->fg = SV_BLACK;
    } else if (!sd->card_present) {
        text = "NO SD";
        out->bg = SV_RED;
        out->fg = SV_WHITE;
    } else if (sd->mounted) {
        text = "SD OK";
        out->bg = SV_GREEN;
        out->fg = SV_BLACK;
    } else if (text_is(sd->status_text, "Card Full")) {
        text = "SD FULL";
        out->bg = SV_RED;
        out->fg = SV_WHITE;
    } else if (text_is(sd->status_text, "Card Not Ready")) {
        text = "SD WAIT";               /* in the slot, not mounted yet */
        out->bg = SV_YELLOW;
        out->fg = SV_BLACK;
    } else {
        text = "SD ERR";
        out->bg = SV_RED;
        out->fg = SV_WHITE;
    }
    put_centred(out->text, SV_CHIP_W, text);
}

/* -----------------------------------------------------------------------
 * sv_build_footer
 * ----------------------------------------------------------------------- */
/* Line 2's FX field: the selected effect, and while its file is being
 * made how far it is (yellow, like PAUSED), or N/A when
 * the original plays instead (dark grey, like "FX NONE"). */
static void fx_field(const ui_state_t *s, sv_footer_t *out)
{
    char        t[SV_LINE1_W + 1U];
    const char *name = ui_effect_name(s->active_effect);

    if (ui_is_preparing(s)) {
        snprintf(t, sizeof(t), "FX %s %u%%", name, (unsigned)s->prep_pct);   /* widest "FX PITCH DOWN 100%" */
        out->fx_colour = SV_YELLOW;
    } else if (s->fx_na) {
        snprintf(t, sizeof(t), "FX %s N/A", name);
        out->fx_colour = SV_DARKGREY;
    } else {
        snprintf(t, sizeof(t), "FX %s", name);
        out->fx_colour = (s->active_effect == EFFECT_NONE) ? SV_DARKGREY : SV_LIGHTGREY;
    }
    put_left(out->fx, SV_FX_W, t, true);
}

void sv_build_footer(const ui_state_t *s, const sv_sd_in_t *sd, uint8_t rec_left_s,
                     const char *notice, bool notice_info, sv_footer_t *out)
{
    char        t[SV_LINE1_W + 1U];
    const char *name = "";

    if (s == NULL || out == NULL) {
        return;
    }
    memset(out, 0, sizeof(*out));
    sv_sd_chip(sd, &out->chip);
    if (sd != NULL && sd->current_name != NULL) {
        name = sd->current_name;
    }

    /* Line 1. "%.12s": an 8.3 name is 12 characters at most, and the
     * name is never read past them. */
    if (notice != NULL && notice[0] != '\0') {
        snprintf(t, sizeof(t), "%s", notice);
        out->line1_colour = notice_info ? SV_LIGHTGREY : SV_ORANGE;
    } else if (s->playback == PLAYBACK_RECORDING) {
        if (rec_left_s == SV_REC_LEFT_UNKNOWN) {
            snprintf(t, sizeof(t), "REC %.12s", name);
        } else if (rec_left_s == 0U) {
            snprintf(t, sizeof(t), "SAVING %.12s", name);    /* time is up */
        } else {
            snprintf(t, sizeof(t), "REC %u:%02u %.12s", (unsigned)(rec_left_s / 60U),
                     (unsigned)(rec_left_s % 60U), name);
        }
        out->line1_colour = SV_RED;
    } else if (ui_is_preparing(s)) {
        snprintf(t, sizeof(t), "PREPARING %.12s", name);   /* plays by itself when made */
        out->line1_colour = SV_YELLOW;
    } else if (s->playback == PLAYBACK_PLAYING) {
        snprintf(t, sizeof(t), "PLAYING %.12s", name);
        out->line1_colour = SV_GREEN;
    } else if (s->playback == PLAYBACK_PAUSED) {
        snprintf(t, sizeof(t), "PAUSED %.12s", name);
        out->line1_colour = SV_YELLOW;
    } else {
        t[0] = '\0';
        out->line1_colour = SV_LIGHTGREY;
    }
    put_left(out->line1, SV_LINE1_W, t, true);

    /* Line 2: the effect, and MUTE. Locked, the speaker is off anyway and
     * the header's red SPEAKER LOCKED says why, so MUTE is not shown. */
    fx_field(s, out);
    put_left(out->mute, SV_MUTE_W, (s->muted && !s->speaker_locked) ? "MUTE" : "", false);
    out->mute_colour = SV_RED;
}

/* -----------------------------------------------------------------------
 * sv_refusal_text
 * The same first-match order as sv_sd_chip(), so the notice and the chip
 * beside it always tell the same story.
 * ----------------------------------------------------------------------- */

/* One refusal reason, worded for each command Jack can refuse. */
typedef struct {
    const char *rec;                    /* RECORD_START refused */
    const char *play;                   /* PLAY_START refused   */
} refusal_t;

static const refusal_t s_try_again  = { "REC: TRY AGAIN",     "PLAY: TRY AGAIN"     };
static const refusal_t s_on_pc      = { "REC: SD CARD ON PC", "PLAY: SD CARD ON PC" };
static const refusal_t s_no_card    = { "REC: NO SD CARD",    "PLAY: NO SD CARD"    };
static const refusal_t s_no_files   = { "REC: TRY AGAIN",     "PLAY: NO RECORDINGS" };   /* REC needs none */
static const refusal_t s_card_full  = { "REC: SD CARD FULL",  "PLAY: SD CARD FULL"  };
static const refusal_t s_not_ready  = { "REC: SD NOT READY",  "PLAY: SD NOT READY"  };
static const refusal_t s_card_error = { "REC: SD CARD ERROR", "PLAY: SD CARD ERROR" };

const char *sv_refusal_text(bool record, const sv_sd_in_t *sd, uint16_t file_count)
{
    const refusal_t *r;

    if (sd == NULL || !sd->have_status) {
        r = &s_try_again;               /* nothing known yet */
    } else if (sd->msc_mode) {
        r = &s_on_pc;
    } else if (sd->recording || sd->playing != SV_PLAYING_IDLE || sd->fx_busy) {
        r = &s_try_again;               /* still busy with a file */
    } else if (!sd->card_present) {
        r = &s_no_card;
    } else if (sd->mounted) {
        /* A good card: nothing to play, or one file would not open */
        r = (file_count == 0U) ? &s_no_files : &s_try_again;
    } else if (text_is(sd->status_text, "Card Full")) {
        r = &s_card_full;
    } else if (text_is(sd->status_text, "Card Not Ready")) {
        r = &s_not_ready;               /* in the slot, not mounted yet */
    } else {
        r = &s_card_error;
    }
    return record ? r->rec : r->play;
}

/* -----------------------------------------------------------------------
 * sv_answer_notice
 * The table in status_view.h, one helper per command.
 * ----------------------------------------------------------------------- */

/* Fill out: text (cut to the line), colour and pop-up. */
static void set_notice(sv_notice_t *out, const char *text, bool info, bool popup)
{
    snprintf(out->text, sizeof(out->text), "%s", text);
    out->info  = info;
    out->popup = popup;
}

/* REC or PLAY: an accepted start ends any notice, unless the file plays
 * without its effect (this file cannot have effects); a refusal says why,
 * worded from Jack's status as the SD chip is, and opens the pop-up, but
 * a PLAY of a file that has gone (the list changed) only says so. */
static void start_notice(bool record, bool ok, uint8_t detail, const sv_sd_in_t *sd,
                         uint16_t file_count, sv_notice_t *out)
{
    if (ok && !record && detail == (uint8_t)SV_ACK_NO_FX) {
        set_notice(out, "NO FX FOR THIS FILE", true, false);
        return;
    }
    if (ok) {
        set_notice(out, "", false, false);
        return;
    }
    if (!record && detail == (uint8_t)SV_ACK_NOT_FOUND) {
        set_notice(out, "PLAY: FILE GONE", false, false);
        return;
    }
    set_notice(out, sv_refusal_text(record, sd, file_count), false, true);
}

/* DELETE: its answer comes in Jack's status, after the list has closed
 * up, so it only ever says something in the footer: no pop-up, no beep. */
static void delete_notice(bool ok, uint8_t detail, const sv_sd_in_t *sd, const char *name,
                          sv_notice_t *out)
{
    if (ok) {
        snprintf(out->text, sizeof(out->text), "DELETED %.12s", (name != NULL) ? name : "");
        out->info  = true;
        out->popup = false;
        return;
    }
    if (detail == (uint8_t)SV_ACK_NOT_FOUND) {
        set_notice(out, "DELETE: FILE GONE", false, false);
    } else if (detail == (uint8_t)SV_ACK_BUSY) {
        bool on_pc = (sd != NULL) && sd->have_status && sd->msc_mode;
        set_notice(out, on_pc ? "DELETE: SD CARD ON PC" : "DELETE: SD BUSY", false, false);
    } else {
        set_notice(out, "DELETE: CARD ERROR", false, false);
    }
}

void sv_answer_notice(sv_cmd_t cmd, bool ok, uint8_t detail, const sv_sd_in_t *sd,
                      uint16_t file_count, const char *name, sv_notice_t *out)
{
    if (out == NULL) {
        return;
    }
    memset(out, 0, sizeof(*out));
    if (cmd == SV_CMD_DELETE) {
        delete_notice(ok, detail, sd, name, out);
    } else {
        start_notice(cmd == SV_CMD_RECORD, ok, detail, sd, file_count, out);
    }
}

/* -----------------------------------------------------------------------
 * sv_notice_active
 * The unsigned difference read as signed is negative while until_ms is
 * still ahead, also when the tick count wraps in between (the same test
 * tony_ui.c uses for its other timers).
 * ----------------------------------------------------------------------- */
bool sv_notice_active(uint32_t now_ms, uint32_t until_ms)
{
    return (int32_t)(now_ms - until_ms) < 0;
}

/* -----------------------------------------------------------------------
 * sv_sanitize
 * The ILI9341 font has glyphs for 0x20..0x7F only, and its Draw_Char
 * indexes past the font for bytes above that. Names come from the SD
 * card (a PC can write any byte), so they are fixed before drawing.
 * ----------------------------------------------------------------------- */
void sv_sanitize(char *text, size_t len)
{
    if (text == NULL || len == 0U) {
        return;
    }
    for (size_t i = 0U; i < len; i++) {
        unsigned char c = (unsigned char)text[i];
        if (c == '\0') {
            return;
        }
        if (c < 0x20U || c > 0x7EU) {
            text[i] = '?';
        }
    }
    text[len - 1U] = '\0';              /* no NUL in the buffer: end it */
}
